"""argv dispatch and output. Parsing lives here; logic in the domain modules."""
import sys

from . import DomainError, UsageError, parse_ts
from . import escalation, grouping, ingest, rotation, store, timeline


def split_args(args, flags=(), valued=(), multi=()):
    """Separate positionals from options; returns (pos, flagset, opts, multis)."""
    pos, flagset, opts, multis = [], set(), {}, {}
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in flags:
            flagset.add(arg)
            i += 1
        elif arg in valued or arg in multi:
            if i - 1 >= len(args):
                raise UsageError("missing value for %s" % arg)
            if arg in multi:
                multis.setdefault(arg, []).append(args[i + 1])
            else:
                opts[arg] = args[i + 1]
            i += 2
        elif arg.startswith("--"):
            raise UsageError("unknown option: %s" % arg)
        else:
            pos.append(arg)
            i += 1
    return pos, flagset, opts, multis


def positionals(pos, *names):
    if len(pos) != len(names):
        raise UsageError("expected arguments: %s" % " ".join(names))
    return pos


def required(opts, name):
    if name not in opts:
        raise UsageError("missing %s" % name)
    return opts[name]


def timestamp(raw):
    if parse_ts(raw) is None:
        raise UsageError("bad timestamp '%s'" % raw)
    return raw


def integer(raw, name, minimum):
    try:
        value = int(raw)
    except ValueError:
        raise UsageError("bad value for %s: '%s'" % (name, raw))
    if value < minimum:
        raise UsageError("bad value for %s: '%s'" % (name, raw))
    return value


def require_sub(args, sub):
    if not args or args[0] != sub:
        raise UsageError("expected subcommand: %s" % sub)
    return args[1:]


def cmd_rotation(args, state, now):
    args = require_sub(args, "add")
    pos, _, opts, _ = split_args(args, valued=("--people", "--start", "--shift-hours"))
    (name,) = positionals(pos, "NAME")
    people = required(opts, "--people").split(",")
    if not people or not all(people):
        raise UsageError("empty people list")
    start = timestamp(required(opts, "--start"))
    shift_hours = integer(required(opts, "--shift-hours"), "--shift-hours", 1)
    rotation.add_rotation(state, name, people, start, shift_hours)
    return True, ["added rotation %s" % name]


def cmd_override(args, state, now):
    args = require_sub(args, "add")
    pos, _, opts, _ = split_args(args, valued=("--from", "--until"))
    name, person = positionals(pos, "ROTATION", "PERSON")
    from_ts = timestamp(required(opts, "--from"))
    until_ts = timestamp(required(opts, "--until"))
    if not from_ts < until_ts:
        raise UsageError("--from must be before --until")
    rotation.add_override(state, name, person, from_ts, until_ts)
    return True, ["added override on %s" % name]


def cmd_oncall(args, state, now):
    pos, _, opts, _ = split_args(args, valued=("--at",))
    (name,) = positionals(pos, "ROTATION")
    at = timestamp(opts.get("--at", now))
    return False, [rotation.on_call(state, name, at)]


def cmd_handoffs(args, state, now):
    pos, _, opts, _ = split_args(args, valued=("--count", "--at"))
    (name,) = positionals(pos, "ROTATION")
    count = integer(required(opts, "--count"), "--count", 1)
    at = timestamp(opts.get("--at", now))
    return False, ["%s %s" % pair for pair in rotation.handoffs(state, name, count, at)]


def cmd_policy(args, state, now):
    args = require_sub(args, "add")
    pos, _, _, multis = split_args(args, multi=("--step",))
    (name,) = positionals(pos, "NAME")
    steps = multis.get("--step", [])
    if not steps:
        raise UsageError("at least one --step is required")
    escalation.add_policy(state, name, steps)
    return True, ["added policy %s" % name]


def cmd_route(args, state, now):
    args = require_sub(args, "add")
    pos, _, _, _ = split_args(args)
    service, policy = positionals(pos, "SERVICE", "POLICY")
    escalation.add_route(state, service, policy)
    return True, ["routed %s to %s" % (service, policy)]


def cmd_ingest(args, state, now):
    pos, flagset, opts, _ = split_args(args, flags=("--strict",), valued=("--window",))
    (path,) = positionals(pos, "FILE")
    window = grouping.DEFAULT_WINDOW
    if "--window" in opts:
        window = integer(opts["--window"], "--window", 1)
    summary = ingest.ingest(
        state, path, "--strict" in flagset, window,
        report=lambda message: print(message, file=sys.stderr),
    )
    return True, [summary]


def cmd_ack(args, state, now):
    pos, _, opts, _ = split_args(args, valued=("--by",))
    (inc_id,) = positionals(pos, "INCIDENT")
    person = required(opts, "--by")
    escalation.ack(state, inc_id, person, now)
    return True, ["acked %s" % inc_id]


def cmd_resolve(args, state, now):
    pos, _, _, _ = split_args(args)
    (inc_id,) = positionals(pos, "INCIDENT")
    escalation.resolve(state, inc_id, now)
    return True, ["resolved %s" % inc_id]


def cmd_tick(args, state, now):
    positionals(split_args(args)[0])
    lines = escalation.tick(state, now)
    return True, lines or ["no pages due"]


def cmd_list(args, state, now):
    pos, flagset, _, _ = split_args(args, flags=("--all",))
    positionals(pos)
    incidents = sorted(state["incidents"], key=grouping.incident_number)
    if "--all" not in flagset:
        incidents = [inc for inc in incidents if inc["status"] != "resolved"]
    lines = [
        "%s %s %s %s alerts=%d last=%s"
        % (inc["id"], inc["status"], inc["severity"], grouping.fingerprint(inc),
           len(inc["alerts"]), inc["last_seen"])
        for inc in incidents
    ]
    return False, lines or ["no incidents"]


def cmd_timeline(args, state, now):
    pos, _, opts, _ = split_args(args, valued=("--format",))
    (inc_id,) = positionals(pos, "INCIDENT")
    fmt = opts.get("--format", "text")
    if fmt not in ("text", "json"):
        raise UsageError("bad format '%s'" % fmt)
    inc = grouping.find_incident(state, inc_id)
    if fmt == "json":
        return False, [timeline.render_json(inc)]
    return False, timeline.render_text(inc)


COMMANDS = {
    "rotation": cmd_rotation,
    "override": cmd_override,
    "oncall": cmd_oncall,
    "handoffs": cmd_handoffs,
    "policy": cmd_policy,
    "route": cmd_route,
    "ingest": cmd_ingest,
    "ack": cmd_ack,
    "resolve": cmd_resolve,
    "tick": cmd_tick,
    "list": cmd_list,
    "timeline": cmd_timeline,
}


def main(argv, *, now, state_path):
    try:
        state = store.load(state_path)
    except store.CorruptState:
        print("error: state file is corrupt: %s" % state_path, file=sys.stderr)
        return 2
    try:
        if not argv:
            raise UsageError("missing command")
        command = COMMANDS.get(argv[0])
        if command is None:
            raise UsageError("unknown command: %s" % argv[0])
        mutated, lines = command(argv[1:], state, now)
    except UsageError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 2
    except DomainError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1
    except ingest.StrictAbort as exc:
        print(exc.message, file=sys.stderr)
        return 1
    if mutated:
        store.save(state, state_path)
    for line in lines:
        print(line)
    return 0

