// Shared JSON-RPC 2.0 client for the RPC gateway.
//
// Handles the three framing mistakes the per-service implementations made:
// - batch responses are correlated by id, never by array position
// - batch error entries surface as JsonRpcError values in position, not drops
// - notifications carry no id field and their transport return is ignored

export type Transport = (req: string) => Promise<string>;

export class JsonRpcError extends Error {
  code: number;
  data: unknown;

  constructor(code: number, message: string, data?: unknown) {
    super(message);
    this.name = 'JsonRpcError';
    this.code = code;
    this.data = data;
  }
}

type Params = object | unknown[] | null;

interface ResponseObject {
  jsonrpc: string;
  id?: number | string | null;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}

function buildRequest(id: number | undefined, method: string, params: Params): Record<string, unknown> {
  const req: Record<string, unknown> = { jsonrpc: '2.0' };
  if (id !== undefined) req.id = id;
  req.method = method;
  if (params !== null) req.params = params;
  return req;
}

function unwrap(res: ResponseObject): unknown {
  if (res.error !== undefined) {
    throw new JsonRpcError(res.error.code, res.error.message, res.error.data);
  }
  return res.result;
}

export class JsonRpcClient {
  #transport: Transport;
  #nextId = 1;

  constructor(transport: Transport) {
    this.#transport = transport;
  }

  async call(method: string, params: Params): Promise<unknown> {
    const id = this.#nextId++;
    const raw = await this.#transport(JSON.stringify(buildRequest(id, method, params)));
    return unwrap(JSON.parse(raw) as ResponseObject);
  }

  async notify(method: string, params: Params): Promise<void> {
