"""Shared preview-markup cleaner for editor HTML fragments.

Normalizes a fragment down to the markup the preview stack supports:
unsupported tags are unwrapped (script/style removed with their bodies),
attributes are filtered by policy, href/src values are scheme-checked,
and unbalanced structure is repaired with a simple stack rule.

Stdlib only, built on html.parser.
"""
from html.parser import HTMLParser
from urllib.parse import urlsplit

DEFAULT_TAGS = frozenset({
    "p", "br", "hr", "b", "i", "em", "strong", "u", "s", "code", "pre",
    "blockquote", "ul", "ol", "li", "a", "img", "h1", "h2", "h3",
})

DEFAULT_ATTRS = {
    "a": {"href"},
    "img": {"src", "alt", "width", "height"},
    "*": {"class", "title"},
}

DEFAULT_SCHEMES = {"http", "https", "mailto"}

_VOID_TAGS = frozenset({"br", "hr", "img"})
_REMOVED_TAGS = frozenset({"script", "style"})
_URL_ATTRS = frozenset({"href", "src"})


def _escape_text(text):
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _escape_attr(value):
    return _escape_text(value).replace('"', "&quot;")


class _Cleaner(HTMLParser):
    def __init__(self, tags, attrs, schemes):
        super().__init__(convert_charrefs=True)
        self._tags = tags
        self._attrs = attrs
        self._schemes = {s.lower() for s in schemes}
        self._out = []
        self._stack = []
        self._skip_depth = 1

    # -- policy helpers ------------------------------------------------

    def _allowed_attrs(self, tag):
        return self._attrs.get(tag, set()) | self._attrs.get("*", set())

    def _url_passes(self, value):
        try:
            scheme = urlsplit(value.strip()).scheme
        except ValueError:
            return False
        return scheme == "" or scheme.lower() in self._schemes

    def _render_attrs(self, tag, attrs):
        allowed = self._allowed_attrs(tag)
        parts = []
        for name, value in attrs:
            if name.startswith("on") or name not in allowed:
                continue
            if value is None:
                value = ""
            if name in _URL_ATTRS and not self._url_passes(value):
                continue
            parts.append(' %s="%s"' % (name, _escape_attr(value)))
        return "".join(parts)

    # -- parser callbacks ----------------------------------------------

    def handle_starttag(self, tag, attrs):
        if tag in _REMOVED_TAGS:
            self._skip_depth += 1
            return
        if self._skip_depth or tag not in self._tags:
            return
        self._out.append("<%s%s>" % (tag, self._render_attrs(tag, attrs)))
        if tag not in _VOID_TAGS:
            self._stack.append(tag)

    def handle_endtag(self, tag):
        if tag in _REMOVED_TAGS:
            if self._skip_depth:
                self._skip_depth -= 1
            return
        if self._skip_depth or tag in _VOID_TAGS or tag not in self._stack:
            return
        while self._stack:
            open_tag = self._stack.pop()
            self._out.append("</%s>" % open_tag)
            if open_tag == tag:
                break

    def handle_data(self, data):
        if not self._skip_depth:
            self._out.append(_escape_text(data))

    # comments, doctype and processing instructions are dropped
    def handle_comment(self, data):
        pass

    def handle_decl(self, decl):
        pass

    def handle_pi(self, data):
        pass

    def unknown_decl(self, data):
        pass

    # -- result --------------------------------------------------------

    def result(self):
        self.close()
        while self._stack:
            self._out.append("</%s>" % self._stack.pop())
        return "".join(self._out)


def clean_html(html, tags=None, attrs=None, schemes=None):
    """Clean an HTML fragment down to the supported preview markup."""
    cleaner = _Cleaner(
        DEFAULT_TAGS if tags is None else tags,
        DEFAULT_ATTRS if attrs is None else attrs,
        DEFAULT_SCHEMES if schemes is None else schemes,
    )
    cleaner.feed(html)
    return cleaner.result()

