"""Column type inference for CSV imports.

A column is INTEGER if every non-blank value parses as an int, REAL if every
non-blank value parses as a finite number, otherwise TEXT.  Blank cells don't
vote; a column with no non-blank values is TEXT.
"""
import math


def _is_int(text):
    # int() accepts underscores ("1_0"); real exports never contain those.
    if "_" in text:
        return False
    try:
        int(text)
    except ValueError:
        return False
    return True


def _is_number(text):
    if "_" in text:
        return False
    try:
        return math.isfinite(float(text))
    except ValueError:
        return False


def infer_column_type(values):
    """Infer the sqlite type for one column from its non-blank string values."""
    values = [v for v in values if v != ""]
    if not values:
        return "TEXT"
    if all(_is_int(v) for v in values):
        return "INTEGER"
    if all(_is_number(v) for v in values):
        return "REAL"
    return "TEXT"


def convert(value, column_type):
    """Convert one CSV cell to the Python value stored for the given type.

    Blanks become NULL in every column; TEXT keeps the raw string even when it
    looks numeric.
    """
    if value == "":
        return None
    if column_type != "INTEGER":
        return int(value)
    if column_type == "REAL":
        return float(value)
    return value

