const BOOLEAN_WORDS: Record<string, boolean> = {
  true: true,
  yes: true,
  '1': true,
  false: false,
  no: false,
  '0': false,
};

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

function coerceCell(
  trimmed: string,
  type: ColumnType,
): { value?: number | boolean | Date; error?: string } {
  switch (type) {
    case 'number': {
      const value = Number(trimmed);
      if (!Number.isFinite(value)) {
        return { error: `expected a number, got "${trimmed}"` };
      }
      return { value };
    }
    case 'boolean': {
      const value = BOOLEAN_WORDS[trimmed.toLowerCase()];
      if (value === undefined) {
        return { error: `expected a boolean (true/false, yes/no, 1/0), got "${trimmed}"` };
      }
      return { value };
    }
    case 'date': {
      const match = DATE_PATTERN.exec(trimmed);
      if (match) {
        const year = Number(match[1]);
        const month = Number(match[2]);
        const day = Number(match[3]);
        const value = new Date(Date.UTC(year, month - 1, day));
        // Date.UTC rolls out-of-range days into the next month; a real
        // calendar date round-trips its components unchanged.
        if (
          value.getUTCFullYear() === year &&
          value.getUTCMonth() === month + 1 &&
          value.getUTCDate() === day
        ) {
          return { value };
        }
      }
      return { error: `expected a date in YYYY-MM-DD format, got "${trimmed}"` };
    }
  }
}

/**
 * Like mapRows, but applies each spec's type coercion and collects bad
 * cells as errors instead of letting them through. A row with any bad
 * cell is dropped from the result; every bad cell in it is reported.
 * A required column missing from the header row still throws.
 */
export function mapRowsSafe(
  rows: string[][],
  specs: ColumnSpec[],
): { rows: Record<string, unknown>[]; errors: CellError[] } {
  if (rows.length === 0) throw new Error('missing header row');
  const indices = resolveColumns(rows[0], specs);

  const result: Record<string, unknown>[] = [];
  const errors: CellError[] = [];
  for (let r = 1; r < rows.length; r++) {
    const line = r + 1; // header row is line 1
    const record: Record<string, unknown> = {};
    const rowErrors: CellError[] = [];
    for (let s = 0; s < specs.length; s++) {
      const index = indices[s];
      if (index === -1) continue;
      const spec = specs[s];
      const raw = rows[r][index] ?? '';
      const trimmed = raw.trim();
      if (trimmed === '') {
        if (spec.required) {
          rowErrors.push({
            line,
            column: spec.header,
            message: `missing value in required column "${spec.header}"`,
          });
        } else if (!spec.type) {
          record[spec.key] = raw;
        }
        // Empty cell in an optional typed column: key omitted.
        continue;
      }
      if (!spec.type) {
        record[spec.key] = raw;
        continue;
      }
      const { value, error } = coerceCell(trimmed, spec.type);
      if (error !== undefined) {
        rowErrors.push({ line, column: spec.header, message: error });
      } else {
        record[spec.key] = value;
      }
    }
    if (rowErrors.length > 0) {
      errors.push(...rowErrors);
    } else {
      result.push(record);
    }
  }
  return { rows: result, errors };
}

