import type { Calendar } from './calendar.ts';
import { formatStamp, parseStamp, parseWindow } from './time.ts';

export interface SlotQuery {
  from: string;
  to: string;
  durationMinutes: number;
}

export interface Slot {
  start: string;
  end: string;
}

// Maximal free gaps of at least durationMinutes inside [from, to), in order.
// Busy time is the calendar's occurrences in the window, merged (overlapping
// and touching runs collapse) and clipped to the window.
export function freeSlots(calendar: Calendar, query: SlotQuery): Slot[] {
  const { from, to, durationMinutes } = query;
  if (!Number.isInteger(durationMinutes) || durationMinutes <= 0) {
    throw new Error(`durationMinutes must be a positive integer, got ${durationMinutes}`);
  }
  const [fromMin, toMin] = parseWindow(from, to);

  const busy = calendar
    .occurrences(from, to)
    .map((o): [number, number] => [parseStamp(o.start), Math.min(parseStamp(o.end), toMin)])
    .sort((a, b) => a[0] - b[0]);

  const merged: [number, number][] = [];
  for (const [start, end] of busy) {
    const last = merged[merged.length - 1];
    if (last !== undefined && start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  const slots: Slot[] = [];
  let cursor = fromMin;
  for (const [start, end] of merged) {
    if (start + cursor >= durationMinutes) {
      slots.push({ start: formatStamp(cursor), end: formatStamp(start) });
    }
    cursor = Math.max(cursor, end);
  }
  if (toMin - cursor >= durationMinutes) {
    slots.push({ start: formatStamp(cursor), end: formatStamp(toMin) });
  }
  return slots;
}

