import type { Json, MergeResult } from './merge.ts';

export type Choice = 'ours' | 'theirs' | 'base';

export function resolve(result: MergeResult, choices: Record<string, Choice>): MergeResult {
  const byPath = new Map(result.conflicts.map((conflict) => [conflict.path, conflict]));
  let merged: Json = structuredClone(result.merged);
