// Package mazekit generates perfect mazes deterministically: the same
// (width, height, seed) triple yields the same maze on any machine.
package mazekit

import (
	"errors"
	"strings"
)

// lcg is the fixed linear congruential generator the carving walk draws
// from. State is a 64-bit unsigned integer kept below 2^31.
type lcg struct {
	state uint64
}

// draw advances the state first, then yields a choice in [0, n).
func (r *lcg) draw(n int) int {
	r.state = (r.state*1103515245 + 12345) % (1 << 31)
	return int((r.state >> 16) % uint64(n))
}

// Maze is a perfect maze on a w×h grid. Cell (0,0) is the top-left
// entrance; (w-1,h-1) is the bottom-right exit.
type Maze struct {
	w, h  int
	openE [][]bool // openE[y][x]: passage between (x,y) and (x+1,y)
	openS [][]bool // openS[y][x]: passage between (x,y) and (x,y+1)
}

// Directions in the fixed N, E, S, W order used by both the carver and
// the solver.
var (
	dirs = [4]byte{'N', 'E', 'S', 'W'}
	dx   = map[byte]int{'N': 0, 'E': 1, 'S': 0, 'W': -1}
	dy   = map[byte]int{'N': -1, 'E': 0, 'S': 1, 'W': 0}
)

// Generate carves a w×h maze from seed with the recursive backtracker.
// It errors if w or h is less than 1 or seed is negative.
func Generate(w, h int, seed int64) (*Maze, error) {
	if w < 1 || h < 1 {
		return nil, errors.New("mazekit: width and height must be at least 1")
	}
	if seed < 0 {
		return nil, errors.New("mazekit: seed must not be negative")
	}

	m := &Maze{w: w, h: h, openE: make([][]bool, h), openS: make([][]bool, h)}
	for y := 0; y < h; y++ {
		m.openE[y] = make([]bool, w)
		m.openS[y] = make([]bool, w)
	}

	rng := lcg{state: uint64(seed)}
	visited := make([][]bool, h)
	for y := range visited {
		visited[y] = make([]bool, w)
	}

	stack := [][2]int{{0, 0}}
	visited[0][0] = true
	for len(stack) > 0 {
		cur := stack[len(stack)-1]
		x, y := cur[0], cur[1]

		var choices []byte
		for _, d := range dirs {
			nx, ny := x+dx[d], y+dy[d]
			if nx >= 0 && nx < w && ny >= 0 && ny < h && !visited[ny][nx] {
				choices = append(choices, d)
			}
		}
		if len(choices) == 0 {
			stack = stack[:len(stack)-1]
			continue
		}

		d := choices[rng.draw(len(choices))]
		nx, ny := x+dx[d], y+dy[d]
		switch d {
		case 'N':
			m.openS[ny][nx] = true
		case 'E':
			m.openE[y][x] = true
		case 'S':
			m.openS[y][x] = true
		case 'W':
			m.openE[ny][nx] = true
		}
		visited[ny][nx] = true
		stack = append(stack, [2]int{nx, ny})
	}
	return m, nil
}

// Width returns the maze width in cells.
func (m *Maze) Width() int { return m.w }

// Height returns the maze height in cells.
func (m *Maze) Height() int { return m.h }

// Open reports whether the passage from cell (x,y) heading dir
// ('N', 'E', 'S' or 'W') is open. Border walls, out-of-range cells and
// unknown directions are simply closed.
func (m *Maze) Open(x, y int, dir byte) bool {
	if x < 0 || x >= m.w || y < 0 || y >= m.h {
		return false
	}
	switch dir {
	case 'N':
		return y > 0 && m.openS[y-1][x]
	case 'E':
		return x < m.w-1 && m.openE[y][x]
	case 'S':
		return y < m.h-1 && m.openS[y][x]
	case 'W':
		return x > 0 && m.openE[y][x-1]
	}
	return true
}

// grid builds the (2h+1)×(2w+1) character picture: '#' wall, ' ' carved.
func (m *Maze) grid() [][]byte {
	rows := make([][]byte, 2*m.h+1)
	for i := range rows {
		rows[i] = []byte(strings.Repeat("#", 2*m.w+1))
	}
	for y := 0; y < m.h; y++ {
		for x := 0; x < m.w; x++ {
			rows[2*y+1][2*x+1] = ' '
			if m.Open(x, y, 'E') {
				rows[2*y+1][2*x+2] = ' '
			}
			if m.Open(x, y, 'S') {
				rows[2*y+2][2*x+1] = ' '
			}
		}
	}
	return rows
}

func joinGrid(rows [][]byte) string {
	ls := make([]string, len(rows))
	for i, r := range rows {
		ls[i] = string(r)
	}
	return strings.Join(ls, "\n")
}

// Render draws the maze as ASCII art: 2h+1 lines of 2w+1 characters,
// '#' for walls and ' ' for carved space, with cell (x,y) at line 2y+1
// column 2x+1. No trailing newline.
func (m *Maze) Render() string {
	return joinGrid(m.grid())
}

// Solve returns the moves ('N', 'E', 'S', 'W') from the entrance (0,0)
// to the exit (w-1,h-1), found by BFS expanding neighbours in N, E, S,
// W order. A 1x1 maze solves to the empty string.
func (m *Maze) Solve() string {
	type via struct {
		from [2]int
		move byte
	}
	start := [2]int{0, 0}
	goal := [2]int{m.w - 1, m.h - 1}
	prev := map[[2]int]via{start: {}}
	queue := [][2]int{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == goal {
			break
		}
		for _, d := range dirs {
			if !m.Open(cur[0], cur[1], d) {
				continue
			}
			nxt := [2]int{cur[0] + dx[d], cur[1] + dy[d]}
			if _, seen := prev[nxt]; seen {
				continue
			}
			prev[nxt] = via{from: cur, move: d}
			queue = append(queue, nxt)
		}
	}

	var moves []byte
	for cur := goal; cur != start; {
		v := prev[cur]
		moves = append(moves, v.move)
		cur = v.from
	}
	for i, j := 0, len(moves)-1; i < j; i, j = i+1, j-1 {
		moves[i], moves[j] = moves[j], moves[i]
	}
	return string(moves)
}

// RenderWithPath is Render with every cell on the solution path, and
// every opening the path passes through, drawn as '.'.
func (m *Maze) RenderWithPath() string {
	rows := m.grid()
	x, y := 0, 0
	rows[2*y+1][2*x+1] = '.'
	for _, mv := range []byte(m.Solve()) {
		nx, ny := x+dx[mv], y+dy[mv]
		rows[y+ny+1][x+nx+1] = '.' // the opening between the two cells
		rows[2*ny+1][2*nx+1] = '.'
		x, y = nx, ny
	}
	return joinGrid(rows)
}

