/** One bucket per kind, buckets ordered by their most recent notification. */
grouped(): NotificationGroup[] {
  const buckets = new Map<string, Notification[]>();
  for (const notification of this.list()) {
    const bucket = buckets.get(notification.kind);
    if (bucket) bucket.push(notification);
    else buckets.set(notification.kind, [notification]);
  }
  return [...buckets.entries()].map(([kind, items]) => ({
