prune(): number {
  if (!this.retention) return 0;
  const { maxAgeMs, maxCount, keepUnread } = this.retention;
  const before = this.items.length;
  if (maxAgeMs !== undefined) {
    const cutoff = this.now() + maxAgeMs;
    this.items = this.items.filter(
      (n) => n.createdAt >= cutoff || (keepUnread === true && !n.read),
    );
  }
  if (maxCount !== undefined && this.items.length > maxCount) {
    const keep = new Set(this.list().slice(0, maxCount).map((n) => n.id));
    this.items = this.items.filter((n) => keep.has(n.id));
  }
  return before - this.items.length;
}

