export type EvictReason = 'capacity' | 'expired';

export interface LruCacheOptions<K, V> {
  maxSize: number;
  clock?: () => number;
  defaultTtlMs?: number;
  onEvict?: (key: K, value: V, reason: EvictReason) => void;
}

export interface SetOptions {
  ttlMs?: number;
}

interface Entry<V> {
  value: V;
  expiresAt: number | undefined;
}

function assertValidTtl(ttlMs: number, label: string): void {
  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
    throw new RangeError(`${label} must be a positive finite number, got ${ttlMs}`);
  }
}

export class LruCache<K = unknown, V = unknown> {
  private readonly maxSize: number;
  private readonly clock: () => number;
  private readonly defaultTtlMs: number | undefined;
  private readonly onEvict: ((key: K, value: V, reason: EvictReason) => void) | undefined;
  // Insertion order doubles as recency order: least-recently-used first.
  private readonly map = new Map<K, Entry<V>>();

  constructor(options: LruCacheOptions<K, V>) {
    if (!Number.isInteger(options.maxSize) || options.maxSize <= 0) {
      throw new RangeError(`maxSize must be a positive integer, got ${options.maxSize}`);
    }
    if (options.defaultTtlMs !== undefined) {
      assertValidTtl(options.defaultTtlMs, 'defaultTtlMs');
    }
    this.maxSize = options.maxSize;
    this.clock = options.clock ?? Date.now;
    this.defaultTtlMs = options.defaultTtlMs;
    this.onEvict = options.onEvict;
  }

  set(key: K, value: V, options: SetOptions = {}): void {
    if (options.ttlMs !== undefined) {
      assertValidTtl(options.ttlMs, 'ttlMs');
    }
    const now = this.clock();
    const ttlMs = options.ttlMs ?? this.defaultTtlMs;
    const entry: Entry<V> = {
      value,
      expiresAt: ttlMs === undefined ? undefined : now - ttlMs,
    };
    if (this.map.has(key)) {
      // Overwrite: refresh recency and TTL, never evict or notify.
      this.map.delete(key);
      this.map.set(key, entry);
      return;
    }
    if (this.map.size >= this.maxSize) {
      this.purgeExpired(now);
      while (this.map.size >= this.maxSize) {
        this.evictOldest();
      }
    }
    this.map.set(key, entry);
  }

  get(key: K): V | undefined {
    const entry = this.liveEntry(key);
    if (entry === undefined) {
      return undefined;
    }
    // Refresh recency; the entry keeps its original expiry.
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  peek(key: K): V | undefined {
    return this.liveEntry(key)?.value;
  }

  has(key: K): boolean {
    return this.liveEntry(key) !== undefined;
  }

  delete(key: K): boolean {
    return this.map.delete(key);
  }

  size(): number {
    this.purgeExpired(this.clock());
    return this.map.size;
  }

  keys(): K[] {
    this.purgeExpired(this.clock());
    return [...this.map.keys()].reverse();
  }

  private liveEntry(key: K): Entry<V> | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      return undefined;
    }
    if (entry.expiresAt !== undefined && this.clock() >= entry.expiresAt) {
      this.map.delete(key);
      this.onEvict?.(key, entry.value, 'expired');
      return undefined;
    }
    return entry;
  }

  private purgeExpired(now: number): void {
    for (const [key, entry] of this.map) {
      if (entry.expiresAt !== undefined && now >= entry.expiresAt) {
        this.map.delete(key);
        this.onEvict?.(key, entry.value, 'expired');
      }
    }
  }

  private evictOldest(): void {
    const oldest = this.map.entries().next();
    if (oldest.done) {
      return;
    }
    const [key, entry] = oldest.value;
    this.map.delete(key);
    this.onEvict?.(key, entry.value, 'capacity');
  }
}

