    if (options.ttlMs !== undefined) {
      assertValidTtl(options.ttlMs, 'ttlMs');
    }
    const now = this.clock();
    const ttlMs = options.ttlMs ?? this.defaultTtlMs;
    const entry: Entry<V> = {
      value,
      expiresAt: ttlMs === undefined ? undefined : now + ttlMs,
