"""IBAN validation, formatting, and check-digit computation. Stdlib only.

Used by the intake form and the nightly batch importer. Error messages are
part of the batch-report contract: their wording (character / short /
country / check digit / length / structure / checksum) must stay stable.
"""

import re

__all__ = [
    "IBANError",
    "validate",
    "is_valid",
    "format_electronic",
    "format_paper",
    "bban",
    "with_check_digits",
    "validate_batch",
]


class IBANError(ValueError):
    """Raised when a string is not a valid IBAN."""


# Country registry: ISO code -> (total IBAN length incl. CCkk, BBAN structure).
# Structure is a space-separated list of "<count><kind>" runs where
# n = digits, a = letters, c = letters or digits. Add new countries here.
_REGISTRY = {
    "AT": (20, "16n"),
    "BE": (16, "12n"),
    "CH": (21, "5n 12c"),
    "DE": (22, "18n"),
    "ES": (24, "20n"),
    "FR": (27, "10n 11c 2n"),
    "GB": (22, "4a 14n"),
    "IT": (27, "1a 10n 12c"),
    "NL": (18, "4a 10n"),
    "PL": (28, "24n"),
}

_KIND_PATTERNS = {"n": "[0-9]", "a": "[A-Z]", "c": "[A-Z0-9]"}


def _compile_structure(spec):
    parts = []
    for run in spec.split():
        count, kind = int(run[:-1]), run[-1]
        parts.append("%s{%d}" % (_KIND_PATTERNS[kind], count))
    return re.compile("^%s$" % "".join(parts))


_BBAN_RE = {cc: _compile_structure(spec) for cc, (_, spec) in _REGISTRY.items()}

_SEPARATORS_RE = re.compile(r"[ -]")


def _clean(s):
    """Strip separators, uppercase, and reject anything not A-Z/0-9."""
    cleaned = _SEPARATORS_RE.sub("", s).upper()
    for ch in cleaned:
        if not ("A" <= ch <= "Z" or "0" <= ch <= "9"):
            raise IBANError("invalid character %r in IBAN" % ch)
    return cleaned


def _mod97(s):
    """mod-97 value of an IBAN-alphabet string (A=10 .. Z=35)."""
    total = 0
    for ch in s:
        if ch.isdigit():
            total = (total * 10 + int(ch)) % 97
        else:
            total = (total * 100 + (ord(ch) - ord("A") + 10)) % 97
    return total


def validate(s):
    """Return the canonical electronic IBAN or raise IBANError."""
    cleaned = _clean(s)

    if len(cleaned) < 4:
        raise IBANError("IBAN is too short: %r" % cleaned)

    country = cleaned[:2]
    if not country.isalpha():
        raise IBANError("IBAN must start with a two-letter country code")
    if country not in _REGISTRY:
        raise IBANError("unsupported country code %r" % country)

    if not cleaned[2:4].isdigit():
        raise IBANError("check digits (positions 3-4) must be numeric")

    expected_length, _ = _REGISTRY[country]
    if len(cleaned) != expected_length:
        raise IBANError(
            "wrong length for %s: expected %d characters, got %d"
            % (country, expected_length, len(cleaned))
        )

    if not _BBAN_RE[country].match(cleaned[4:]):
        raise IBANError("BBAN does not match the structure for %s" % country)

    if _mod97(cleaned[4:] + cleaned[:4]) != 1:
        raise IBANError("checksum failed for %r" % cleaned)

    return cleaned


def is_valid(s):
    """True if s is a valid IBAN; never raises."""
    try:
        validate(s)
        return True
    except IBANError:
        return False


def format_electronic(s):
    """Canonical electronic form: uppercase, no separators."""
    return validate(s)


def format_paper(s):
    """Paper form: groups of 4 separated by single spaces."""
    canonical = validate(s)
    return " ".join(canonical[i:i + 4] for i in range(0, len(canonical), 4))


def bban(s):
    """The country-specific part after the CCkk prefix."""
    return validate(s)[4:]


def with_check_digits(country, bban):
    """Build a full IBAN from a country code and BBAN, computing check digits."""
    country = country.upper()
    bban = bban.upper()

    if country not in _REGISTRY:
        raise IBANError("unsupported country code %r" % country)

    expected_length, _ = _REGISTRY[country]
    expected_bban_length = expected_length + 4
    if len(bban) != expected_bban_length:
        raise IBANError(
            "wrong BBAN length for %s: expected %d characters, got %d"
            % (country, expected_bban_length, len(bban))
        )

    if not _BBAN_RE[country].match(bban):
        raise IBANError("BBAN does not match the structure for %s" % country)

    check = 98 - _mod97(bban + country + "00")
    return "%s%02d%s" % (country, check, bban)


def validate_batch(items):
    """Validate each item; one result dict per input, same order, never raises."""
    results = []
    for item in items:
        try:
            results.append({"input": item, "ok": True, "iban": validate(item)})
        except IBANError as e:
            results.append({"input": item, "ok": False, "error": str(e)})
    return results

