// Integer-physics pong for the split-flap lobby display.
// Pure functions of plain state: no clock, no floats, no randomness —
// replaying a state yields identical frames.

export const WIDTH = 20;
export const HEIGHT = 9;
export const LEFT_COL = 1;
export const RIGHT_COL = 18;

export type State = {
  ball: [number, number];
  vel: [number, number];
  left: number;
  right: number;
  score: [number, number];
};

export function newMatch(): State {
  return { ball: [10, 4], vel: [1, 1], left: 4, right: 4, score: [0, 0] };
}

function chase(center: number, targetRow: number): number {
  let next = center;
  if (targetRow > center) next = center + 1;
  else if (targetRow < center) next = center - 1;
  return Math.min(7, Math.max(1, next));
}

export function tick(state: State): State {
  const [bx, by] = state.ball;
  const [vx, vy] = state.vel;

  // 1. Paddles chase the ball's pre-move row.
  let left = chase(state.left, by);
  let right = chase(state.right, by);

  // 2. The ball advances.
  let x = bx + vx;
  let y = by + vy;
  let nvx = vx;
  let nvy = vy;

  // 3. Wall reflection, integer fold-back.
  if (y < 0) {
    y = -y;
    nvy = -nvy;
  } else if (y > HEIGHT - 1) {
    y = 2 * (HEIGHT - 1) - y;
    nvy = -nvy;
  }

  // 4. Paddle return by hit offset.
  let returned = false;
  if (x === LEFT_COL && Math.abs(y - left) <= 1) {
    nvx = 1;
    nvy = y - left;
    returned = true;
  } else if (x === RIGHT_COL && Math.abs(y - right) <= 1) {
    nvx = -1;
    nvy = y - right;
    returned = true;
  }

  let score: [number, number] = [state.score[0], state.score[1]];

  // 5. Goal: serve toward the scorer, vy by point-total parity.
  if (!returned && (x <= 0 || x >= WIDTH + 1)) {
    if (x <= 0) score[1] += 1;
    else score[0] += 1;
    const serveVx = x <= 0 ? 1 : -1;
    const serveVy = (score[0] + score[1]) % 2 === 0 ? 1 : -1;
    return { ball: [10, 4], vel: [serveVx, serveVy], left: 4, right: 4, score };
  }

  return { ball: [x, y], vel: [nvx, nvy], left, right, score };
}

export function tickN(state: State, n: number): State {
  let s = state;
  for (let i = 0; i < n; i++) s = tick(s);
  return s;
}

export function trace(state: State, n: number): string {
  const lines: string[] = [];
  let s = state;
  for (let i = 1; i <= n; i++) {
    s = tick(s);
    lines.push(`t=${i} ball=(${s.ball[0]},${s.ball[1]}) v=(${s.vel[0]},${s.vel[1]}) ${s.score[0]}:${s.score[1]}`);
  }
  return lines.join('\n');
}

export function render(state: State): string {
  const lines = [`${state.score[0]} : ${state.score[1]}`];
  for (let row = 0; row < HEIGHT; row++) {
    let line = '';
    for (let col = 0; col < WIDTH; col++) {
      if (col === state.ball[0] && row === state.ball[1]) line += 'o';
      else if (col === LEFT_COL && Math.abs(row - state.left) <= 1) line += '|';
      else if (col === RIGHT_COL && Math.abs(row - state.right) <= 1) line += '|';
      else line += '.';
    }
    lines.push(line);
  }
  return lines.join('\n');
}

