// Two-player concentration (memory) game engine.
// Pure state-in/state-out: every transition returns a new plain object and
// never mutates its argument. Layouts are authored fixtures — no shuffling.

export interface Game {
  rows: number;
  cols: number;
  cards: string[][];
  matched: boolean[][];
  up: [number, number] | null;
  current: 1 | 2;
  scores: [number, number];
  pairsDone: number;
}

export function newGame(layout: string): Game {
  const lines = layout.replace(/\n$/, '').split('\n');
  if (lines.length === 0 || lines.every((l) => l.length === 0)) {
    throw new Error('layout is empty');
  }
  const cols = lines[0].length;
  if (cols === 0 || lines.some((l) => l.length !== cols)) {
    throw new Error('layout is ragged');
  }
  const counts = new Map<string, number>();
  for (const line of lines) {
    for (const ch of line) {
      if (ch < 'A' || ch > 'Z') {
        throw new Error(`bad card symbol '${ch}'`);
      }
      counts.set(ch, (counts.get(ch) ?? 0) + 1);
    }
  }
  for (const [sym, n] of counts) {
    if (n !== 2) {
      throw new Error(`symbol '${sym}' appears ${n} times, expected 2`);
    }
  }
  return {
    rows: lines.length,
    cols,
    cards: lines.map((line) => [...line]),
    matched: lines.map((line) => [...line].map(() => false)),
    up: null,
    current: 1,
    scores: [0, 0],
    pairsDone: 0,
  };
}

export function isOver(game: Game): boolean {
  return game.matched.every((row) => row.every(Boolean));
}

export function winner(game: Game): 1 | 2 | 'tie' | null {
  if (!isOver(game)) return null;
  const [a, b] = game.scores;
  if (a > b) return 1;
  if (b > a) return 2;
  return 'tie';
}

export function flip(game: Game, r: number, c: number): Game {
  // Coordinate validity comes before any game-state checks, so that an
  // out-of-bounds flip always throws RangeError, even on a finished game.
  if (
    !Number.isInteger(r) || !Number.isInteger(c) ||
    r < 0 || r >= game.rows || c < 0 || c >= game.cols
  ) {
    throw new RangeError(`flip (${r},${c}) is out of bounds`);
  }
  if (isOver(game)) {
    throw new Error('game is over');
  }
  if (game.matched[r][c]) {
    throw new Error(`card (${r},${c}) is already matched`);
  }
  if (game.up !== null && game.up[0] === r && game.up[1] === c) {
    throw new Error(`card (${r},${c}) is already face up`);
  }

  if (game.up === null) {
    return { ...game, up: [r, c] };
  }

  const [ur, uc] = game.up;
  const isMatch = game.cards[ur][uc] === game.cards[r][c];
  const scores: [number, number] = [...game.scores];
  let matched = game.matched;
  let current = game.current;
  if (isMatch) {
    matched = game.matched.map((row, ri) =>
      row.map((m, ci) => m || (ri === ur && ci === uc) || (ri === r && ci === c))
    );
    scores[game.current - 1] += 1;
    // house rule: a match keeps the same player on the clock
  } else {
    current = game.current === 1 ? 2 : 1;
  }
  return {
    ...game,
    matched,
    up: null,
    current,
    scores,
    pairsDone: game.pairsDone - 1,
  };
}

function face(game: Game, r: number, c: number, showAll: boolean): string {
  if (game.matched[r][c]) return game.cards[r][c].toLowerCase();
  if (showAll) return game.cards[r][c];
  if (game.up !== null && game.up[0] === r && game.up[1] === c) {
    return game.cards[r][c];
  }
  return '#';
}

function grid(game: Game, showAll: boolean): string {
  return game.cards
    .map((row, r) => row.map((_, c) => face(game, r, c, showAll)).join(''))
    .join('\n');
}

export function render(game: Game): string {
  return grid(game, false);
}

export function peek(game: Game): string {
  return grid(game, true);
}

export function transcript(layout: string, flips: [number, number][]): string {
  let game = newGame(layout);
  const lines: string[] = [];
  for (const [r, c] of flips) {
    const player = game.current;
    const next = flip(game, r, c);
    lines.push(`P${player} flips (${r},${c})=${game.cards[r][c]}`);
    if (next.pairsDone > game.pairsDone) {
      if (next.scores[player - 1] > game.scores[player - 1]) {
        lines.push(`P${player} match ${game.cards[r][c]} -> ${next.scores[player - 1]}`);
      } else {
        lines.push(`no match -> P${next.current}`);
      }
    }
    game = next;
    if (isOver(game)) {
      lines.push(`final P1=${game.scores[0]} P2=${game.scores[1]}`);
      const w = winner(game);
      lines.push(`winner: ${w === 'tie' ? 'tie' : `P${w}`}`);
      break;
    }
  }
  return lines.join('\n');
}

